{{// === 数据读取与配置定义 === }}
{{// 目的: 读取所有相关变量，构建 config 对象并通过 define() 广播 }}
{{// 注意: 永远不要手动修改此条目的 EJS 代码！变量的初始值和阈值应在初始化脚本中设置。 }}
<%_
// --- 读取 配置阈值 变量 (必须先读取，提供默认值以防初始化失败) ---
const Config_关系确认好感度门槛 = parseInt(getvar('变量.Config.通用.关系确认好感度门槛') || 200);

const Config_白露_适应度1上限 = parseInt(getvar('变量.Config.夏白露.适应度阶段1上限') || 100);
const Config_白露_适应度2上限 = parseInt(getvar('变量.Config.夏白露.适应度阶段2上限') || 500);
const Config_白露_师徒值1上限 = parseInt(getvar('变量.Config.夏白露.师徒值阶段1上限') || 50);
const Config_白露_师徒值2上限 = parseInt(getvar('变量.Config.夏白露.师徒值阶段2上限') || 101);
const Config_白露_师徒值3上限 = parseInt(getvar('变量.Config.夏白露.师徒值阶段3上限') || 201);
const Config_白露_师徒值4上限 = parseInt(getvar('变量.Config.夏白露.师徒值阶段4上限') || 500);
const Config_白露_好感度1上限 = parseInt(getvar('变量.Config.夏白露.好感度阶段1上限') || 50);
const Config_白露_好感度2上限 = parseInt(getvar('变量.Config.夏白露.好感度阶段2上限') || 101);
const Config_白露_好感度3上限 = parseInt(getvar('变量.Config.夏白露.好感度阶段3上限') || 201);
const Config_白露_好感度4上限 = parseInt(getvar('变量.Config.夏白露.好感度阶段4上限') || 500);
const Config_修罗场_白露师徒值门槛 = parseInt(getvar('变量.Config.修罗场.夏白露师徒值门槛') || 200);

const Config_蒹葭_适应度1上限 = parseInt(getvar('变量.Config.夏蒹葭.适应度阶段1上限') || 100);
const Config_蒹葭_适应度2上限 = parseInt(getvar('变量.Config.夏蒹葭.适应度阶段2上限') || 500);
const Config_蒹葭_师徒值1上限 = parseInt(getvar('变量.Config.夏蒹葭.师徒值阶段1上限') || 50);
const Config_蒹葭_师徒值2上限 = parseInt(getvar('变量.Config.夏蒹葭.师徒值阶段2上限') || 101);
const Config_蒹葭_师徒值3上限 = parseInt(getvar('变量.Config.夏蒹葭.师徒值阶段3上限') || 201);
const Config_蒹葭_师徒值4上限 = parseInt(getvar('变量.Config.夏蒹葭.师徒值阶段4上限') || 500);
const Config_蒹葭_好感度1上限 = parseInt(getvar('变量.Config.夏蒹葭.好感度阶段1上限') || 50);
const Config_蒹葭_好感度2上限 = parseInt(getvar('变量.Config.夏蒹葭.好感度阶段2上限') || 101);
const Config_蒹葭_好感度3上限 = parseInt(getvar('变量.Config.夏蒹葭.好感度阶段3上限') || 201);
const Config_蒹葭_好感度4上限 = parseInt(getvar('变量.Config.夏蒹葭.好感度阶段4上限') || 500);
const Config_修罗场_蒹葭师徒值门槛 = parseInt(getvar('变量.Config.修罗场.夏蒹葭师徒值门槛') || 500);
const Config_修罗场_蒹葭好感度门槛 = parseInt(getvar('变量.Config.修罗场.夏蒹葭好感度门槛') || 500);


// --- 读取 夏白露 相关变量 ---
const 白露_适应度 = parseInt(getvar('变量.夏白露.适应度') || 0);
const 白露_好感度 = parseInt(getvar('变量.夏白露.好感度') || 0);
const 白露_师徒值 = parseInt(getvar('变量.夏白露.师徒值') || 0); // 反映夏白露视角的关系
const 白露_主角关系 = parseInt(getvar('变量.夏白露.主角关系') || 0); // 0=未确定, 1=确定

// --- 读取 夏蒹葭 相关变量 ---
const 蒹葭_适应度 = parseInt(getvar('变量.夏蒹葭.适应度') || 0);
const 蒹葭_好感度 = parseInt(getvar('变量.夏蒹葭.好感度') || 0);
const 蒹葭_师徒值 = parseInt(getvar('变量.夏蒹葭.师徒值') || 0); // 反映夏蒹葭视角的关系
const 蒹葭_主角关系 = parseInt(getvar('变量.夏蒹葭.主角关系') || 0); // 0=未确定, 1=确定


// --- 构建 config 对象 ---
const config = {
  // 阈值配置 (方便后续在阶段判断中直接使用 config.阈值.xxx)
  阈值: {
    通用: {
      关系确认好感度门槛: Config_关系确认好感度门槛,
    },
    夏白露: {
      适应度阶段1上限: Config_白露_适应度1上限,
      适应度阶段2上限: Config_白露_适应度2上限,
      师徒值阶段1上限: Config_白露_师徒值1上限,
      师徒值阶段2上限: Config_白露_师徒值2上限,
      师徒值阶段3上限: Config_白露_师徒值3上限,
      师徒值阶段4上限: Config_白露_师徒值4上限,
      好感度阶段1上限: Config_白露_好感度1上限,
      好感度阶段2上限: Config_白露_好感度2上限,
      好感度阶段3上限: Config_白露_好感度3上限,
      好感度阶段4上限: Config_白露_好感度4上限,
    },
    夏蒹葭: {
      适应度阶段1上限: Config_蒹葭_适应度1上限,
      适应度阶段2上限: Config_蒹葭_适应度2上限,
      师徒值阶段1上限: Config_蒹葭_师徒值1上限,
      师徒值阶段2上限: Config_蒹葭_师徒值2上限,
      师徒值阶段3上限: Config_蒹葭_师徒值3上限,
      师徒值阶段4上限: Config_蒹葭_师徒值4上限,
      好感度阶段1上限: Config_蒹葭_好感度1上限,
      好感度阶段2上限: Config_蒹葭_好感度2上限,
      好感度阶段3上限: Config_蒹葭_好感度3上限,
      好感度阶段4上限: Config_蒹葭_好感度4上限,
    },
    修罗场: {
      夏白露师徒值门槛: Config_修罗场_白露师徒值门槛,
      夏蒹葭师徒值门槛: Config_修罗场_蒹葭师徒值门槛,
      夏蒹葭好感度门槛: Config_修罗场_蒹葭好感度门槛,
    }
  },
  // 角色状态
  夏白露: {
    适应度: 白露_适应度,
    好感度: 白露_好感度,
    师徒值: 白露_师徒值,
    主角关系: 白露_主角关系,
  },
  夏蒹葭: {
    适应度: 蒹葭_适应度,
    好感度: 蒹葭_好感度,
    师徒值: 蒹葭_师徒值,
    主角关系: 蒹葭_主角关系,
  },
};

// --- 广播 config 对象 ---
// 这使得其他 WI 条目可以通过 config.xxx 访问这些值
define('config', config);
_%>

